(()=>{
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const APP=document.getElementById('app'), TOAST=document.getElementById('toast');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const WORLD_IDS=['code-station','bunker','rocket','infiltration','assault'];
const session={mode:'remote',role:null,token:null,user:null,worldOverrides:{},progressRoot:null};
let accessPoll=null;
let resources={blocks:[],units:[]}, curriculum={meta:{},n2:[],criteria:[],sessions:[],evaluations:[],resources:[]}, view='home', selectedResource=null, selectedBlock='ALL', searchTerm='', activeWorld=null, activeMission=null, teacherStudents=[], selectedStudent=null, teacherTab='class', teacherReferenceDate=(new Date()).toISOString().slice(0,10), teacherShowAllSkills=false;

let WORLDS={};
function defaultPlatform(){return {version:7,callsign:null,completedUnits:{},worldProgress:{},evidence:[],lastView:'home',lastWorld:null};}
function platform(){
  if(!session.progressRoot || typeof session.progressRoot!=='object') session.progressRoot={};
  if(!session.progressRoot.platform || typeof session.progressRoot.platform!=='object') session.progressRoot.platform=defaultPlatform();
  const p=session.progressRoot.platform;
  p.completedUnits=p.completedUnits||{}; p.worldProgress=p.worldProgress||{}; p.evidence=Array.isArray(p.evidence)?p.evidence:[];
  return p;
}
function wp(id){const p=platform(); if(!p.worldProgress[id])p.worldProgress[id]={completed:{},drafts:{},xp:0}; return p.worldProgress[id];}
function missionDone(world,id){return !!wp(world).completed[id];}
function worldFinalDone(world){const w=WORLDS[world];const f=w.missions.find(m=>m.final);return f?missionDone(world,f.id):false;}
function worldUnlocked(id){const w=WORLDS[id];if(w.defaultUnlocked)return true;if(session.worldOverrides?.[id])return true;return w.requires?worldFinalDone(w.requires):true;}
function worldPercent(id){const w=WORLDS[id],done=w.missions.filter(m=>missionDone(id,m.id)).length;return Math.round(done/w.missions.length*100);}
function completedUnit(code){return !!platform().completedUnits[code];}
function toggleUnit(code,val=true){platform().completedUnits[code]=!!val;saveProgress();}
function recordEvidence(codes,score,meta={}){sendHost({type:'eden:event',eventType:'mission_completed',payload:{codes,score,meta,files:missionDraft(activeWorld,WORLDS[activeWorld].missions.find(m=>m.id===activeMission)).files}});}
function toast(msg){TOAST.textContent=msg;TOAST.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>TOAST.classList.remove('show'),2600);}
async function api(path,{method='GET',body=null,auth=true}={}){const headers={'Accept':'application/json'};if(body!==null)headers['Content-Type']='application/json';if(auth&&session.token)headers.Authorization='Bearer '+session.token;const r=await fetch(path,{method,headers,body:body!==null?JSON.stringify(body):undefined,cache:'no-store'});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.error||data.detail||`Erreur ${r.status}`);return data;}
function stopAccessPoll(){if(accessPoll){clearInterval(accessPoll);accessPoll=null;}}
function startAccessPoll(){stopAccessPoll();accessPoll=setInterval(async()=>{if(session.role!=='student'||!session.token)return;try{const r=await api('/api/me/access');const next=r.worldOverrides||{};if(JSON.stringify(next)!==JSON.stringify(session.worldOverrides||{})){session.worldOverrides=next;toast('Accès professeur mis à jour');if(!activeWorld)renderStudent();}}catch(_){}},15000);}
async function saveProgress(){sendHost({type:'eden:progress',progress:platform()});}
async function loadResources(){const [r,c]=await Promise.all([fetch('/data/resources.json',{cache:'force-cache'}),fetch('/data/curriculum-a1.json',{cache:'force-cache'})]);resources=await r.json();curriculum=await c.json();}

function terminalLog(lines){return `<div class="terminalbox">${lines.map(x=>`<div class="${x[0]}">${esc(x[1])}</div>`).join('')}</div>`;}
function renderAuth(tab='student',status=null){
  const term=status||[['wait','> SIGNAL PÉDAGOLAB détecté'],['','> Canal sécurisé prêt'],['','> En attente d’identification…']];
  APP.innerHTML=`<div class="auth-screen"><div class="auth-card"><section class="auth-art"><div><div class="eyebrow">PÉDAGOLAB // WORLDS</div><h1 style="font-size:34px;margin:8px 0 10px">Apprendre. Jouer. Construire.</h1><p class="muted">Un même parcours, des ressources communes et plusieurs mondes qui mettent les compétences en situation.</p></div>${terminalLog(term)}<small class="muted">NEXUS V4 · 140 unités pédagogiques · progression centralisée</small></section><section class="auth-form-wrap"><div class="tabs-auth"><button id="studentTab" class="${tab==='student'?'active':''}">Élève</button><button id="teacherTab" class="${tab==='teacher'?'active':''}">Professeur</button></div><div id="authSlot"></div></section></div></div>`;
  $('#studentTab').onclick=()=>renderAuth('student'); $('#teacherTab').onclick=()=>renderAuth('teacher');
  const slot=$('#authSlot');
  if(tab==='student')slot.innerHTML=`<div class="eyebrow">Reprendre ma progression</div><h2>Connexion élève</h2><form id="studentLogin"><div class="field"><label>Identifiant</label><input id="studentUser" autocomplete="username" required placeholder="ex. clara"></div><div class="field"><label>Code d’accès</label><input id="studentPin" type="password" inputmode="numeric" autocomplete="current-password" required placeholder="••••••"></div><button id="loginBtn" class="login-btn" type="submit">Reprendre mon parcours →</button><div id="loginError" class="error"></div></form><p class="muted" style="font-size:12px">Le professeur crée les comptes. Tes cours, tes mondes et tes productions sont restaurés à la connexion.</p>`;
  else slot.innerHTML=`<div class="eyebrow">Pilotage de classe</div><h2>Espace professeur</h2><form id="teacherLogin"><div class="field"><label>PIN professeur</label><input id="teacherPin" type="password" inputmode="numeric" required></div><button id="loginBtn" class="login-btn" type="submit">Ouvrir le tableau de bord →</button><div id="loginError" class="error"></div></form><p class="muted" style="font-size:12px">Débloque un monde sans valider les compétences : l’accès professeur reste distinct de la progression naturelle.</p>`;
  if(tab==='student')$('#studentLogin').onsubmit=studentLogin; else $('#teacherLogin').onsubmit=teacherLogin;
}
function setLoginBusy(on,text='Connexion…'){const b=$('#loginBtn');if(!b)return;b.classList.toggle('loading',on);b.innerHTML=on?`<span class="spinner"></span>${esc(text)}`:(session.role==='teacher'?'Ouvrir le tableau de bord →':'Reprendre mon parcours →');}
async function studentLogin(e){e.preventDefault();const username=$('#studentUser').value.trim().toLowerCase(),pin=$('#studentPin').value;$('#loginError').textContent='';setLoginBusy(true,'Authentification…');let logs=[['wait',`> authentication ${username||'…'}`]];renderAuth('student',logs);$('#studentUser').value=username;$('#studentPin').value=pin;setLoginBusy(true,'Vérification du profil…');try{const r=await api('/api/login/student',{method:'POST',body:{username,pin},auth:false});logs.push(['ok','> profile .............. FOUND']);renderAuth('student',logs);setLoginBusy(true,'Synchronisation…');await sleep(180);session.role='student';session.token=r.token;session.user=r.user;session.worldOverrides=r.worldOverrides||{};session.progressRoot=r.progress||{};logs.push(['ok','> progress ............. RESTORED']);logs.push(['ok',`> welcome ${r.user.displayName}`]);renderAuth('student',logs);setLoginBusy(true,'Ouverture de PédagoLab…');await sleep(260);startAccessPoll();if(!platform().callsign)return renderIntro();view=platform().lastView||'home';renderStudent();}catch(err){renderAuth('student',logs);$('#studentUser').value=username;$('#loginError').textContent=err.message;setLoginBusy(false);}}
async function teacherLogin(e){e.preventDefault();const pin=$('#teacherPin').value;$('#loginError').textContent='';setLoginBusy(true,'Authentification…');try{const r=await api('/api/login/teacher',{method:'POST',body:{pin},auth:false});session.role='teacher';session.token=r.token;session.user=r.user;await loadTeacherStudents();renderTeacher();}catch(err){$('#loginError').textContent=err.message;setLoginBusy(false);}}
function renderIntro(){APP.innerHTML=`<div class="auth-screen"><div class="card" style="width:min(760px,100%);padding:24px"><div class="eyebrow">CODE//OS · message entrant</div><div id="introTerm" class="terminalbox" style="margin:14px 0"><div class="wait">> Signal reçu.</div><div>> Origine : réseau pédagogique NEXUS.</div><div>> Plusieurs secteurs d’apprentissage sont hors ligne.</div><div class="ok">> Mission : SAVE THE SHIP.</div></div><h2>Choisis ton indicatif</h2><p class="muted">Il peut être différent de ton prénom. Il sera utilisé dans l’histoire et tes productions.</p><form id="callsignForm"><div class="field"><label>Indicatif</label><input id="callsign" maxlength="18" required placeholder="NOVA"></div><button class="primary" type="submit">Prendre les commandes →</button></form></div></div>`;$('#callsignForm').onsubmit=async e=>{e.preventDefault();platform().callsign=$('#callsign').value.trim()||session.user.displayName;await saveProgress();view='home';renderStudent();};}
function topbar(active){return `<div class="topbar"><div class="brand">PÉDAGO<span>LAB</span><small>apprendre · pratiquer · produire</small></div><div class="nav"><button data-nav="home" class="${active==='home'?'active':''}">Accueil</button><button data-nav="worlds" class="${active==='worlds'?'active':''}">Mondes</button><button data-nav="resources" class="${active==='resources'?'active':''}">Ressources</button><button data-nav="path" class="${active==='path'?'active':''}">Mon parcours</button></div><div class="userchip"><div class="avatar">${esc((platform().callsign||session.user.displayName)[0]||'?')}</div><div><b>${esc(platform().callsign||session.user.displayName)}</b><div class="muted" style="font-size:10px">${esc(session.user.displayName)}</div></div><button id="logout" class="ghost" style="padding:7px 9px">Quitter</button></div></div>`;}
function bindNav(){$$('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;platform().lastView=view;saveProgress();renderStudent();});$('#logout').onclick=()=>{stopAccessPoll();session.role=null;session.token=null;session.user=null;renderAuth('student');};}
function renderStudent(){if(activeWorld)return renderWorld();const content=view==='resources'?resourcesView():view==='path'?pathView():view==='worlds'?worldsView():homeView();APP.innerHTML=`<div class="shell">${topbar(view)}${content}</div>`;bindNav();bindStudentView();}
function homeView(){const next=nextWorld();const completed=Object.keys(platform().completedUnits).filter(k=>platform().completedUnits[k]).length;const totalWorldDone=WORLD_IDS.reduce((a,id)=>a+WORLDS[id].missions.filter(m=>missionDone(id,m.id)).length,0);return `<section class="hero-card"><div><div class="eyebrow">Bonjour ${esc(platform().callsign||session.user.displayName)}</div><h1>Continue là où tu t’es arrêté.</h1><p class="lead">PédagoLab rassemble les cours NEXUS, les aides et les mondes jouables. Une compétence peut revenir dans plusieurs univers pour vérifier que tu sais la réutiliser.</p><div class="cta-row"><button class="primary" id="continueBtn">▶ Continuer ${esc(WORLDS[next].title)}</button><button class="secondary" data-nav="resources">📚 Chercher une ressource</button></div></div><div class="metricbox"><div class="metric"><b>${completed}</b><span>ressources terminées / ${resources.units.length}</span></div><div class="metric"><b>${totalWorldDone}</b><span>missions réussies</span></div><div class="metric"><b>${WORLD_IDS.filter(worldUnlocked).length}/5</b><span>mondes accessibles</span></div><div class="metric"><b>${WORLD_IDS.filter(worldFinalDone).length}</b><span>productions finales</span></div></div></section><section style="margin-top:24px"><div class="eyebrow">Mondes</div><h2 class="section-title">Une même compétence, plusieurs contextes</h2>${worldCards()}</section><section style="margin-top:24px"><div class="eyebrow">Reprendre autrement</div><h2 class="section-title">Apprendre avant de rejouer</h2><div class="grid three">${recommendedUnits().map(resourceCard).join('')}</div></section>`;}
function worldsView(){return `<div class="eyebrow">Univers jouables</div><h1 class="section-title">Les mondes de PédagoLab</h1><p class="lead">Chaque univers possède sa propre logique de jeu. Les mondes apparaissent réellement quand leurs prérequis sont atteints — ou lorsqu’un professeur ouvre un accès temporaire.</p>${worldCards()}<div class="card" style="margin-top:16px"><b>Pourquoi plusieurs mondes ?</b><p class="muted">Une boucle apprise dans CODE//STATION peut revenir dans ROCKET, INFILTRATION ou ASSAULT. Le but est de transférer le savoir, pas d’apprendre une solution par cœur.</p><a href="/legacy/code-station-v6.html" target="_blank" class="secondary" style="display:inline-block;text-decoration:none">Ouvrir l’ancien CODE//STATION complet ↗</a></div>`;}
function worldCards(){return `<div class="world-map">${WORLD_IDS.map(id=>{const w=WORLDS[id],unlocked=worldUnlocked(id),teach=session.worldOverrides?.[id],pct=worldPercent(id);return `<article class="world-card ${unlocked?'':'locked'} ${teach?'teacher':''}" style="--w1:${w.colors[0]};--w2:${w.colors[1]}"><div class="art"></div><div class="world-icon">${w.icon}</div><h3>${unlocked?esc(w.title):'SIGNAL INCONNU'}</h3><p>${unlocked?esc(w.tagline):'Ce secteur est encore dans l’ombre.'}</p><div class="world-progress"><i style="width:${pct}%"></i></div>${unlocked?`<button class="primary" data-world="${id}">${pct?'Reprendre':'Entrer'}</button>`:`<div class="lockveil">🔒 monde verrouillé</div>`}${teach?'<span class="tag" style="margin-top:8px">ACCÈS PROF</span>':''}</article>`;}).join('')}</div>`;}
function nextWorld(){return WORLD_IDS.find(id=>worldUnlocked(id)&&!worldFinalDone(id))||'code-station';}
function recommendedUnits(){const codes=[...new Set(WORLDS[nextWorld()].resources)].slice(0,3);return codes.map(code=>resources.units.find(u=>u.code===code)).filter(Boolean);}
function resourcesView(){const filtered=resources.units.filter(u=>(selectedBlock==='ALL'||u.blockId===selectedBlock)&&(!searchTerm||(`${u.code} ${u.title} ${u.skillLabel} ${u.lesson}`).toLowerCase().includes(searchTerm.toLowerCase())));return `<div class="eyebrow">Bibliothèque NEXUS</div><h1 class="section-title">Cours, supports et aides</h1><p class="lead">140 unités issues de PédagoLab NEXUS. Tu peux chercher une notion sans lancer un jeu, ou ouvrir une ressource directement depuis une mission.</p><div class="library-toolbar"><input id="searchInput" class="input search" value="${esc(searchTerm)}" placeholder="Rechercher : boucle, flexbox, réseau…"><span class="pill">${filtered.length} ressources</span></div><div class="resource-layout"><aside class="card filters"><button class="filter-btn ${selectedBlock==='ALL'?'active':''}" data-block="ALL">Toutes les compétences</button>${resources.blocks.map(b=>`<button class="filter-btn ${selectedBlock===b.id?'active':''}" data-block="${b.id}"><b>${b.id}</b><br><small>${esc(b.label)}</small></button>`).join('')}</aside><section class="resource-list">${filtered.map(resourceCard).join('')}</section></div>`;}
function resourceCard(u){if(!u)return'';return `<article class="resource-card"><div class="code">${esc(u.code)} · ${esc(u.typology||'Ressource')}</div><h3>${esc(u.title)}</h3><p>${esc(u.opening||u.skillLabel).slice(0,150)}</p><div class="tags"><span class="tag">${esc(u.blockId)}</span>${completedUnit(u.code)?'<span class="tag done">✓ terminé</span>':''}</div><div style="margin-top:11px"><button class="secondary" data-resource="${esc(u.code)}">Ouvrir</button></div></article>`;}
function pathView(){const blockStats=resources.blocks.map(b=>{const units=resources.units.filter(u=>u.blockId===b.id),done=units.filter(u=>completedUnit(u.code)).length;return {...b,total:units.length,done,pct:units.length?Math.round(done/units.length*100):0};});return `<div class="eyebrow">Progression</div><h1 class="section-title">Mon parcours</h1><p class="lead">Les codes du référentiel restent cachés dans le jeu, mais sont visibles ici pour relier les ressources et les preuves de maîtrise.</p><div class="path-grid">${blockStats.map(b=>`<div class="block-progress"><b>${b.id}</b><p class="muted" style="font-size:12px;min-height:48px">${esc(b.label)}</p><div class="barline"><i style="width:${b.pct}%"></i></div><small>${b.done}/${b.total} ressources marquées terminées</small></div>`).join('')}</div><h2 style="margin-top:25px">Mondes</h2><div class="grid three">${WORLD_IDS.map(id=>{const w=WORLDS[id];return `<div class="card"><div style="font-size:28px">${w.icon}</div><h3>${esc(w.title)}</h3><p class="muted">${worldPercent(id)} % · ${w.missions.filter(m=>missionDone(id,m.id)).length}/${w.missions.length} missions</p><div class="barline"><i style="width:${worldPercent(id)}%"></i></div></div>`;}).join('')}</div>`;}
function bindStudentView(){$$('[data-world]').forEach(b=>b.onclick=()=>{activeWorld=b.dataset.world;activeMission=null;platform().lastWorld=activeWorld;saveProgress();renderStudent();});$$('[data-resource]').forEach(b=>b.onclick=()=>openResource(b.dataset.resource));$$('[data-block]').forEach(b=>b.onclick=()=>{selectedBlock=b.dataset.block;renderStudent();});const si=$('#searchInput');if(si)si.oninput=e=>{searchTerm=e.target.value;clearTimeout(si._t);si._t=setTimeout(renderStudent,180)};const c=$('#continueBtn');if(c)c.onclick=()=>{activeWorld=nextWorld();activeMission=null;renderStudent();};}
function openResource(code){const u=resources.units.find(x=>x.code===code);if(!u)return;selectedResource=u;document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="resourceModal"><div class="modal resource-detail"><div class="modal-head"><div>${session.role==='student'?'':`<div class="eyebrow">${esc(u.code)} · ${esc(u.blockId)}</div>`}<h2>${esc(u.title)}</h2><p class="muted">${esc(u.skillLabel)}</p></div><button id="closeResource">Fermer</button></div>${u.opening?`<div class="lesson-block"><h4>Situation</h4><p>${esc(u.opening)}</p></div>`:''}<div class="lesson-block"><h4>Comprendre</h4><p>${esc(u.lesson)}</p></div><div class="lesson-block"><h4>Exemple</h4><p>${esc(u.example)}</p></div><div class="lesson-block"><h4>À faire</h4><p>${esc(u.task)}</p></div><div class="lesson-block"><h4>À réaliser</h4><p>${esc(u.proof)}</p></div><div class="lesson-block"><h4>Transfert</h4><p>${esc(u.transfer)}</p></div>${(u.questions||[]).map((q,i)=>`<div class="question"><b>${esc(q.prompt)}</b><div class="answer-grid">${[q.correct,...(q.distractors||[])].sort(()=>Math.random()-.5).map(a=>`<button data-answer="${esc(a)}" data-correct="${esc(q.correct)}">${esc(a)}</button>`).join('')}</div><small class="muted" data-feedback></small></div>`).join('')}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px"><button class="primary" id="markResource">${completedUnit(u.code)?'✓ Ressource terminée':'Marquer comme terminée'}</button><button class="secondary" id="gotoWorldResource">Voir où l’utiliser</button></div></div></div>`);$('#closeResource').onclick=()=>$('#resourceModal').remove();$('#resourceModal').onclick=e=>{if(e.target.id==='resourceModal')e.currentTarget.remove()};$$('[data-answer]',$('#resourceModal')).forEach(b=>b.onclick=()=>{const q=b.closest('.question'),ok=b.dataset.answer===b.dataset.correct;b.classList.add(ok?'good':'bad');$('[data-feedback]',q).textContent=ok?'Bonne réponse.': 'Réessaie en relisant le cours.';});$('#markResource').onclick=()=>{toggleUnit(u.code,true);$('#markResource').textContent='✓ Ressource terminée';toast('Enregistrement demandé.');};$('#gotoWorldResource').onclick=()=>{const wid=WORLD_IDS.find(id=>WORLDS[id].missions.some(m=>(m.resources||[]).includes(u.code)));if(wid){$('#resourceModal').remove();activeWorld=wid;renderStudent();}else toast('Cette ressource est surtout utilisée hors jeu pour le moment.');};}

function renderWorld(){const w=WORLDS[activeWorld];if(!w||!worldUnlocked(activeWorld)){activeWorld=null;return renderStudent();}const firstAvailable=w.missions.find((m,i)=>i===0||missionDone(activeWorld,w.missions[i-1].id));if(!activeMission)activeMission=firstAvailable?.id||w.missions[0].id;const m=w.missions.find(x=>x.id===activeMission);APP.innerHTML=`<div class="shell world-view" style="--w1:${w.colors[0]};--w2:${w.colors[1]}"><div class="world-head"><div><button id="backHub" class="secondary">← PédagoLab</button></div><div class="userchip"><div class="avatar">${w.icon}</div><div><b>${esc(w.title)}</b><div class="muted" style="font-size:10px">${worldPercent(activeWorld)} %</div></div></div></div><section class="world-banner"><div class="eyebrow">MONDE JOUABLE</div><h1>${w.icon} ${esc(w.title)}</h1><p>${esc(w.desc)}</p></section><div class="mission-grid">${w.missions.map((x,i)=>{const unlocked=x.id===activeMission;return `<button class="mission-node ${missionDone(activeWorld,x.id)?'complete':''} ${unlocked?'':'locked'}" data-mission="${x.id}" ${unlocked?'':'disabled'}><b>${missionDone(activeWorld,x.id)?'✓ ':''}${esc(x.title)}</b><small>${esc(x.skill)}</small></button>`;}).join('')}</div>${missionStage(w,m)}</div>`;$('#backHub').onclick=()=>sendHost({type:'eden:close'});$$('[data-mission]').forEach(b=>b.onclick=()=>{activeMission=b.dataset.mission;renderWorld();});bindMission(w,m);}
function missionStage(w,m){const draft=missionDraft(activeWorld,m);const names=Object.keys(draft.files);const activeFile=draft.activeFile&&names.includes(draft.activeFile)?draft.activeFile:names[0];draft.activeFile=activeFile;const resLinks=(m.resources||[]).map(c=>resources.units.find(u=>u.code===c)).filter(Boolean);return `<div class="mission-stage"><section class="editor-panel"><div class="panel-head"><div><div class="eyebrow">${esc(m.skill)}</div><b>${esc(m.title)}</b></div><span class="tag">${m.final?'ÉVALUATION / PRODUCTION':'MISSION'}</span></div><div class="panel-body"><p class="lead" style="font-size:13px">${esc(m.brief)}</p><div class="code-tabs">${names.map(n=>`<button data-file="${esc(n)}" class="${n===activeFile?'active':''}">${esc(n)}</button>`).join('')}</div><textarea aria-label="Ton code · ${esc(activeFile)}" id="missionCode" class="codearea" spellcheck="false">${esc(draft.files[activeFile])}</textarea><div class="scenario-list" style="margin-top:10px">${m.scenarios.map((s,i)=>`<button data-scenario="${i}" class="scenario ${draft.scenario===i?'active':''}">${esc(s.name)}</button>`).join('')}</div><div class="mission-actions"><button id="saveDraft" class="secondary">Enregistrer</button><button id="testScenario" class="primary">Tester ce scénario</button><button id="validateMission" class="secondary">${m.final?'Valider la production':'Valider tous les scénarios'}</button></div><div id="missionResult" class="resultbox">${draft.lastResult?esc(draft.lastResult):'Teste d’abord le scénario affiché. La validation globale utilise exactement le même code.'}</div><div class="resource-links">${resLinks.map(u=>`<button class="resource-link" data-help-resource="${u.code}">📚 ${esc(u.title)}</button>`).join('')}</div></div></section><section class="sim-panel"><div class="panel-head"><b>Simulation</b><span class="muted">${esc(m.scenarios[draft.scenario].name)}</span></div><div class="panel-body"><div id="simScreen" class="sim-screen">${renderScenarioPreview(m,draft.scenario,draft.lastTest)}</div></div></section></div>`;}
function missionDraft(world,m){const d=wp(world).drafts[m.id]||(wp(world).drafts[m.id]={files:JSON.parse(JSON.stringify(m.files)),activeFile:Object.keys(m.files)[0],scenario:0,lastResult:'',lastTest:null});return d;}
function bindMission(w,m){const d=missionDraft(activeWorld,m);$$('[data-file]').forEach(b=>b.onclick=()=>{saveEditor(d);d.activeFile=b.dataset.file;saveProgress();renderWorld();});$$('[data-scenario]').forEach(b=>b.onclick=()=>{saveEditor(d);d.scenario=+b.dataset.scenario;d.lastTest=null;saveProgress();renderWorld();});$('#saveDraft').onclick=()=>{saveEditor(d);saveProgress();d.lastResult='Enregistrement demandé.';$('#missionResult').textContent=d.lastResult;};$('#testScenario').onclick=async()=>{saveEditor(d);const r=await workerTest(m,d,d.scenario);d.lastTest=r;d.lastResult=r.message;saveProgress();renderWorld();};$('#validateMission').onclick=async()=>{saveEditor(d);let all=true,msgs=[];for(let i=0;i<m.scenarios.length;i++){const r=await workerTest(m,d,i);all=all&&r.pass;msgs.push(`${m.scenarios[i].name}: ${r.pass?'OK':'À corriger'}`);}d.lastResult=msgs.join('\n');if(all){wp(activeWorld).completed[m.id]=true;wp(activeWorld).xp=(wp(activeWorld).xp||0)+(m.final?120:40);recordEvidence(m.resources||[],m.final?3:2,{type:m.final?'game-transfer':'game-mission',transfer:!!m.final,sourceId:`${activeWorld}:${m.id}`,label:m.title,note:`${WORLDS[activeWorld].title} · ${m.title}`});toast(m.final?'Production réussie.':'Mission réussie.');}saveProgress();renderWorld();};$$('[data-help-resource]').forEach(b=>b.onclick=()=>openResource(b.dataset.helpResource));}
function saveEditor(d){const area=$('#missionCode');if(area)d.files[d.activeFile]=area.value;}
function renderScenarioPreview(m,i,last){const s=m.scenarios[i];return `<h3>${esc(s.name)}</h3><p class="muted">Entrées du simulateur</p><pre style="white-space:pre-wrap">${esc(JSON.stringify(s.input,null,2))}</pre>${last?`<div class="resultbox ${last.pass?'ok':'bad'}">${esc(last.message)}</div>`:''}<p class="muted" style="font-size:11px;margin-top:18px">Simulation pédagogique locale : aucun accès au système réel.</p>`;}

async function loadTeacherStudents(){const r=await api('/api/teacher/students');teacherStudents=r.students||[];selectedStudent=selectedStudent&&teacherStudents.find(s=>s.id===selectedStudent.id)||teacherStudents[0]||null;}
function dateValue(v){const d=new Date(v+'T00:00:00');return Number.isNaN(d.getTime())?null:d;}
function criterion(code){return curriculum.criteria.find(c=>c.code===code)||null;}
function n2Def(code){return curriculum.n2.find(c=>c.code===code)||null;}
function evalById(id){return curriculum.evaluations.find(e=>e.id===id)||null;}
function studentPlatform(s){return s?.progress?.platform||defaultPlatform();}
function explicitEvidence(s){const p=studentPlatform(s);return Array.isArray(p.evidence)?p.evidence:[];}
function legacyMissionEvidence(s){const p=studentPlatform(s),wp0=p.worldProgress||{},out=[];for(const wid of WORLD_IDS){const completed=wp0[wid]?.completed||{};for(const m of WORLDS[wid].missions){if(!completed[m.id])continue;for(const code of (m.resources||[]))out.push({id:`legacy:${wid}:${m.id}:${code}`,criterion:code,score:m.final?3:2,type:m.final?'game-transfer':'game-mission',transfer:!!m.final,source:'legacy',sourceId:`${wid}:${m.id}`,label:m.title,date:null});}}return out;}
function studentEvidence(s){const explicit=explicitEvidence(s),ids=new Set(explicit.map(e=>e.sourceId).filter(Boolean));return explicit.concat(legacyMissionEvidence(s).filter(e=>!ids.has(e.sourceId)));}
function evidenceFor(s,code){return studentEvidence(s).filter(e=>e.criterion===code);}
function expectedInfo(code,ref=teacherReferenceDate){const c=criterion(code);if(!c)return {score:null,exposures:0,official:false};const rd=dateValue(ref);const dates=(c.sessionDates||[]).map(dateValue).filter(Boolean).filter(d=>!rd||d<=rd);if(!dates.length)return {score:null,exposures:0,official:false};let score=dates.length>=2?2:1,official=false;for(const id of c.evaluationIds||[]){const ev=evalById(id);const ed=ev?.date?dateValue(ev.date):null;if(ev&&ed&&(!rd||ed<=rd)&&(ev.type==='Évaluation officielle'||ev.type==='Bilan de progression')){score=3;official=true;}}return {score,exposures:dates.length,official};}
function actualInfo(s,code){const ev=evidenceFor(s,code);if(!ev.length)return {score:null,count:0,evidence:[],spaced:false,transfer:false};const strong=ev.filter(x=>Number(x.score)>=2),transfer=ev.some(x=>Number(x.score)>=3&&(x.transfer||['Évaluation officielle','Bilan de progression','game-transfer'].includes(x.type)));let spaced=false;const ds=strong.map(x=>x.date?dateValue(x.date):null).filter(Boolean).sort((a,b)=>a-b);for(let i=0;i<ds.length;i++)for(let j=i+1;j<ds.length;j++)if((ds[j]-ds[i])/(86400000)>=(curriculum.meta.evidenceSpacingDays||7))spaced=true;let score=0;if(ev.some(x=>Number(x.score)>=1))score=1;if(strong.length)score=2;if(strong.length>=2&&transfer&&spaced)score=3;return {score,count:ev.length,evidence:ev,spaced,transfer};}
function isHighStakesLow(info){return info.evidence.some(e=>Number(e.score)<=1&&['Évaluation officielle','Bilan de progression'].includes(e.type));}
function remediationEligible(s,code){const exp=expectedInfo(code),act=actualInfo(s,code);if(exp.score===null||act.score===null||act.score>1)return false;return act.count>=2||isHighStakesLow(act);}
function criterionStatus(s,code){const exp=expectedInfo(code),act=actualInfo(s,code);if(exp.score===null){if(act.score!==null&&act.score>=2)return {label:'En avance',tone:'ahead',expected:null,actual:act.score};return {label:'À venir',tone:'future',expected:null,actual:act.score};}if(act.score===null)return {label:'À observer',tone:'observe',expected:exp.score,actual:null};if(remediationEligible(s,code))return {label:'Remédiation',tone:'remed',expected:exp.score,actual:act.score};const gap=act.score-exp.score;if(gap>=1)return {label:'En avance',tone:'ahead',expected:exp.score,actual:act.score};if(gap>=0)return {label:'Dans le rythme',tone:'ok',expected:exp.score,actual:act.score};return {label:'À consolider',tone:'warn',expected:exp.score,actual:act.score};}
function n2Summary(s,n2code){const d=n2Def(n2code),codes=d?.criteria||[];const relevant=codes.filter(c=>expectedInfo(c).score!==null||actualInfo(s,c).score!==null);const due=codes.filter(c=>expectedInfo(c).score!==null);const observed=due.filter(c=>actualInfo(s,c).score!==null);const rem=due.filter(c=>remediationEligible(s,c));const gaps=observed.map(c=>actualInfo(s,c).score-expectedInfo(c).score);const aheadFuture=codes.filter(c=>expectedInfo(c).score===null&&(actualInfo(s,c).score||0)>=2).length;const avgGap=gaps.length?gaps.reduce((a,b)=>a+b,0)/gaps.length:0;let label='À venir',tone='future';if(due.length){if(!observed.length){label='À observer';tone='observe';}else if(rem.length){label='Remédiation';tone='remed';}else if(avgGap>.4||aheadFuture){label='En avance';tone='ahead';}else if(avgGap<-.35){label='À consolider';tone='warn';}else{label='Dans le rythme';tone='ok';}}else if(aheadFuture){label='En avance';tone='ahead';}const mean=observed.length?observed.reduce((a,c)=>a+actualInfo(s,c).score,0)/observed.length:null;return {label,tone,due:due.length,observed:observed.length,coverage:due.length?observed.length/due.length:0,mean,rem:rem.length,aheadFuture};}
function trajectory(s){const due=curriculum.criteria.filter(c=>expectedInfo(c.code).score!==null),observed=due.filter(c=>actualInfo(s,c.code).score!==null),rem=due.filter(c=>remediationEligible(s,c.code)),gaps=observed.map(c=>actualInfo(s,c.code).score-expectedInfo(c.code).score),future=curriculum.criteria.filter(c=>expectedInfo(c.code).score===null&&(actualInfo(s,c.code).score||0)>=2),mastered=due.filter(c=>actualInfo(s,c.code).score===3);const coverage=due.length?observed.length/due.length:0,avgGap=gaps.length?gaps.reduce((a,b)=>a+b,0)/gaps.length:0;let label='Dans le rythme',tone='ok',action='Continuer la progression prévue';if(coverage<.35){label='Données insuffisantes';tone='observe';action='Collecter davantage de preuves avant de classer';}else if(rem.length>=3||rem.length/Math.max(1,due.length)>=.18){label='Remédiation ciblée';tone='remed';action='Groupe temporaire sur les critères prioritaires';}else if(avgGap<-.55){label='Rythme à sécuriser';tone='warn';action='Consolider avant les prochains jalons';}else if(avgGap>.45||future.length>=3){label='En avance';tone='ahead';action='Proposer transfert / aller plus loin';}return {label,tone,action,due:due.length,observed:observed.length,coverage,avgGap,remediation:rem.length,future:future.length,mastered:mastered.length};}
function toneBadge(label,tone){return `<span class="skill-status ${tone}">${esc(label)}</span>`;}
function plannedStats(){const rd=dateValue(teacherReferenceDate),sessions=curriculum.sessions||[],elapsed=sessions.filter(s=>{const d=dateValue(s.date);return d&&rd&&d<=rd;}).length,due=curriculum.criteria.filter(c=>expectedInfo(c.code).score!==null).length;return {elapsed,total:sessions.length,due,totalCriteria:curriculum.criteria.length,pct:sessions.length?Math.round(elapsed/sessions.length*100):0};}
function classOverview(){const stats=plannedStats(),rows=teacherStudents.map(s=>({s,t:trajectory(s)})),coverage=rows.length?Math.round(rows.reduce((a,x)=>a+x.t.coverage,0)/rows.length*100):0,rem=rows.filter(x=>x.t.tone==='remed').length,ahead=rows.filter(x=>x.t.tone==='ahead').length;return `<div class="teacher-kpis"><div class="teacher-kpi"><b>${stats.pct}%</b><span>année planifiée écoulée</span><small>${stats.elapsed}/${stats.total} séances</small></div><div class="teacher-kpi"><b>${stats.due}/${stats.totalCriteria}</b><span>critères déjà travaillés</span><small>selon le planning à cette date</small></div><div class="teacher-kpi"><b>${coverage}%</b><span>couverture moyenne des preuves</span><small>ne confond pas absence de preuve et difficulté</small></div><div class="teacher-kpi"><b>${rem}</b><span>élèves en remédiation ciblée</span><small>${ahead} en avance</small></div></div><div class="card teacher-card"><div class="section-head"><div><div class="eyebrow">Vue classe</div><h2>Rythme annuel & preuves</h2></div></div><div class="teacher-table-wrap"><table class="teacher-table"><thead><tr><th>Élève</th><th>Lecture</th><th>Preuves</th><th>Maîtrisés</th><th>Remédiation</th><th>Anticipés</th><th>Action suggérée</th></tr></thead><tbody>${rows.map(({s,t})=>`<tr data-student-open="${s.id}"><td><b>${esc(s.displayName)}</b><br><small>${esc(s.username)}</small></td><td>${toneBadge(t.label,t.tone)}</td><td>${Math.round(t.coverage*100)}%<br><small>${t.observed}/${t.due} critères attendus observés</small></td><td>${t.mastered}</td><td>${t.remediation}</td><td>${t.future}</td><td><small>${esc(t.action)}</small></td></tr>`).join('')}</tbody></table></div><p class="teacher-note"><b>Lecture prudente :</b> « données insuffisantes » n’est pas un retard. La remédiation n’est proposée qu’avec plusieurs preuves faibles ou une évaluation forte faible.</p></div>`;}
function selectedStudentPicker(){return `<select id="teacherStudentSelect" class="input">${teacherStudents.map(s=>`<option value="${s.id}" ${selectedStudent?.id===s.id?'selected':''}>${esc(s.displayName)}</option>`).join('')}</select>`;}
function studentDetail(){if(!selectedStudent)return '<div class="card">Aucun élève.</div>';const t=trajectory(selectedStudent),p=studentPlatform(selectedStudent),units=Object.values(p.completedUnits||{}).filter(Boolean).length,wp0=p.worldProgress||{},n2s=curriculum.n2.map(n=>({n,info:n2Summary(selectedStudent,n.code)})).filter(x=>x.info.due||x.info.observed||x.info.aheadFuture);const priority=n2s.sort((a,b)=>({remed:0,warn:1,observe:2,ok:3,ahead:4,future:5}[a.info.tone]-({remed:0,warn:1,observe:2,ok:3,ahead:4,future:5}[b.info.tone])));return `<div class="student-detail-head card"><div><div class="eyebrow">Profil élève</div><div class="student-select-line">${selectedStudentPicker()} ${toneBadge(t.label,t.tone)}</div><p class="muted">${units} ressources terminées · ${studentEvidence(selectedStudent).length} preuves · ${Math.round(t.coverage*100)}% de couverture sur les critères attendus</p></div><div class="student-metrics"><div><b>${t.mastered}</b><span>critères maîtrisés</span></div><div><b>${t.remediation}</b><span>remédiations</span></div><div><b>${t.future}</b><span>critères anticipés</span></div></div></div><div class="grid two teacher-grid"><div class="card"><h3>Compétences à surveiller</h3>${priority.slice(0,18).map(({n,info})=>`<div class="skill-line"><div><b>${esc(n.code)}</b> ${esc(n.title)}</div><div>${toneBadge(info.label,info.tone)} <small>${info.observed}/${info.due||0} observés</small></div></div>`).join('')||'<p class="muted">Aucune compétence observée pour le moment.</p>'}</div><div class="card"><h3>Progression mondes</h3>${WORLD_IDS.map(id=>{const done=Object.values(wp0[id]?.completed||{}).filter(Boolean).length,total=WORLDS[id].missions.length;return `<div style="margin:10px 0"><b>${WORLDS[id].icon} ${esc(WORLDS[id].title)}</b><div class="barline"><i style="width:${Math.round(done/total*100)}%"></i></div><small>${done}/${total} missions</small></div>`;}).join('')}<h3 style="margin-top:18px">Accès professeur</h3><div class="toggle-grid">${WORLD_IDS.map(id=>`<label class="toggle"><span>${WORLDS[id].icon} ${esc(WORLDS[id].title)}</span><input type="checkbox" data-world-toggle="${id}" ${selectedStudent.worldOverrides?.[id]?'checked':''}></label>`).join('')}</div></div></div><div class="card" style="margin-top:14px"><h3>Ajouter une preuve</h3><p class="muted">Utilise cette saisie pour un point de maîtrise, un bilan, une évaluation officielle ou une observation. Une ressource simplement consultée n’est pas une preuve de maîtrise.</p><form id="evidenceForm" class="evidence-form"><select id="evCriterion" class="input" required><option value="">Critère…</option>${curriculum.criteria.map(c=>`<option value="${c.code}">${c.code} · ${esc(c.title)}</option>`).join('')}</select><select id="evScore" class="input"><option value="0">0 · À construire</option><option value="1">1 · Fragile</option><option value="2" selected>2 · En consolidation</option><option value="3">3 · Maîtrisé / transfert</option></select><select id="evType" class="input"><option>Point de maîtrise</option><option>Bilan de progression</option><option>Évaluation officielle</option><option>Observation</option></select><input id="evDate" class="input" type="date" value="${teacherReferenceDate}"><label class="checkline"><input id="evTransfer" type="checkbox"> preuve de transfert</label><input id="evNote" class="input" placeholder="Commentaire court"><button class="primary" type="submit">Ajouter la preuve</button></form></div>`;}
function n2Cell(s,n2code){const i=n2Summary(s,n2code);if(!i.due&&!i.observed&&!i.aheadFuture)return `<td class="heat future">·</td>`;const val=i.mean===null?'?':i.mean.toFixed(1);return `<td class="heat ${i.tone}" title="${esc(i.label)}">${val}</td>`;}
function skillsMap(){const rows=curriculum.n2.filter(n=>teacherShowAllSkills||teacherStudents.some(s=>{const i=n2Summary(s,n.code);return i.due||i.observed||i.aheadFuture;}));return `<div class="card teacher-card"><div class="section-head"><div><div class="eyebrow">Cartographie annuelle</div><h2>Compétences N2 × élèves</h2></div><button id="toggleAllSkills" class="secondary">${teacherShowAllSkills?'Afficher seulement actives':'Afficher les 48 compétences'}</button></div><p class="muted">0 = à construire · 1 = fragile · 2 = consolidation · 3 = maîtrise confirmée. « ? » = prévu mais pas encore observé.</p><div class="heatmap-wrap"><table class="heatmap"><thead><tr><th>Compétence</th>${teacherStudents.map(s=>`<th>${esc(s.displayName)}</th>`).join('')}</tr></thead><tbody>${rows.map(n=>`<tr><th><b>${n.code}</b><small>${esc(n.title)}</small></th>${teacherStudents.map(s=>n2Cell(s,n.code)).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
function remediationView(){const due=curriculum.criteria.filter(c=>expectedInfo(c.code).score!==null),groups=[];for(const c of due){const rem=teacherStudents.filter(s=>remediationEligible(s,c.code));const con=teacherStudents.filter(s=>{const st=criterionStatus(s,c.code);return st.tone==='warn';});if(rem.length||con.length)groups.push({c,rem,con});}groups.sort((a,b)=>b.rem.length-a.rem.length||b.con.length-a.con.length);const next=curriculum.sessions.filter(s=>s.date>=teacherReferenceDate&&String(s.category).includes('REMÉDIATION')).sort((a,b)=>a.date.localeCompare(b.date))[0];const ahead=teacherStudents.filter(s=>trajectory(s).tone==='ahead');return `<div class="teacher-kpis"><div class="teacher-kpi"><b>${groups.reduce((a,g)=>a+g.rem.length,0)}</b><span>signalements remédiation</span><small>par critère, pas par étiquette élève</small></div><div class="teacher-kpi"><b>${groups.length}</b><span>critères à traiter</span><small>avec preuves disponibles</small></div><div class="teacher-kpi"><b>${ahead.length}</b><span>élèves « aller plus loin »</span><small>à proposer, pas à isoler</small></div><div class="teacher-kpi"><b>${next?next.date:'—'}</b><span>prochaine séance dédiée</span><small>${next?esc(next.module):'aucune séance trouvée'}</small></div></div><div class="grid two teacher-grid"><div class="card"><h2>Groupes temporaires suggérés</h2>${groups.slice(0,10).map(g=>`<div class="rem-group"><b>${g.c.code} · ${esc(g.c.title)}</b>${g.rem.length?`<p><span class="skill-status remed">Remédiation</span> ${g.rem.map(s=>esc(s.displayName)).join(', ')}</p>`:''}${g.con.length?`<p><span class="skill-status warn">Consolidation</span> ${g.con.map(s=>esc(s.displayName)).join(', ')}</p>`:''}<small>${esc(g.c.observable||'')}</small></div>`).join('')||'<p class="muted">Pas assez de preuves pour constituer des groupes automatiquement.</p>'}</div><div class="card"><h2>Aller plus loin</h2>${ahead.map(s=>`<div class="skill-line"><b>${esc(s.displayName)}</b><span>${trajectory(s).future} critères anticipés</span></div>`).join('')||'<p class="muted">Aucun élève classé en avance avec suffisamment de preuves.</p>'}<div class="teacher-note" style="margin-top:14px"><b>Principe :</b> les groupes sont temporaires et liés à un critère précis. Un élève peut être en remédiation sur une compétence et en avance sur une autre.</div></div></div>`;}
function calendarView(){const evals=(curriculum.evaluations||[]).filter(e=>e.date>=teacherReferenceDate).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,20),sessions=(curriculum.sessions||[]).filter(s=>s.date>=teacherReferenceDate).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,18);return `<div class="grid two teacher-grid"><div class="card"><div class="eyebrow">Évaluations à venir</div><h2>Plan de preuve</h2>${evals.map(e=>`<div class="calendar-row"><time>${e.date}</time><div><b>${esc(e.id)} · ${esc(e.type)}</b><p>${esc(e.object)}</p><small>${e.criteria.join(' · ')}</small></div></div>`).join('')}</div><div class="card"><div class="eyebrow">Progression prévue</div><h2>Prochaines séances</h2>${sessions.map(s=>`<div class="calendar-row"><time>${s.date}</time><div><b>${esc(s.category)}</b><p>${esc(s.objective).slice(0,170)}</p><small>${esc(s.sequence)} · ${s.criteria.join(' · ')}</small></div></div>`).join('')}</div></div>`;}
function teacherContent(){if(teacherTab==='student')return studentDetail();if(teacherTab==='skills')return skillsMap();if(teacherTab==='remediation')return remediationView();if(teacherTab==='calendar')return calendarView();return classOverview();}
function renderTeacher(){APP.innerHTML=`<div class="shell teacher-shell"><div class="topbar"><div class="brand">PÉDAGO<span>LAB</span><small>pilotage annuel · A1 2026–2027</small></div><div class="teacher-top-actions"><label>Date de référence <input id="teacherRefDate" type="date" value="${teacherReferenceDate}"></label><button id="refreshTeacher" class="secondary">↻ Actualiser</button><button id="teacherLogout" class="ghost">Quitter</button></div></div><nav class="teacher-tabs"><button data-teacher-tab="class" class="${teacherTab==='class'?'active':''}">Vue classe</button><button data-teacher-tab="student" class="${teacherTab==='student'?'active':''}">Élève</button><button data-teacher-tab="skills" class="${teacherTab==='skills'?'active':''}">Cartographie skills</button><button data-teacher-tab="remediation" class="${teacherTab==='remediation'?'active':''}">Remédiation</button><button data-teacher-tab="calendar" class="${teacherTab==='calendar'?'active':''}">Calendrier</button></nav><main id="teacherMain">${teacherContent()}</main></div>`;bindTeacherPanel();}
function bindTeacherPanel(){document.querySelectorAll('[data-teacher-tab]').forEach(b=>b.onclick=()=>{teacherTab=b.dataset.teacherTab;renderTeacher();});const ref=$('#teacherRefDate');if(ref)ref.onchange=()=>{teacherReferenceDate=ref.value||teacherReferenceDate;renderTeacher();};$('#teacherLogout').onclick=()=>{stopAccessPoll();session.role=null;session.token=null;renderAuth('teacher')};$('#refreshTeacher').onclick=async()=>{await loadTeacherStudents();renderTeacher()};document.querySelectorAll('[data-student-open]').forEach(r=>r.onclick=()=>{selectedStudent=teacherStudents.find(s=>s.id===r.dataset.studentOpen)||selectedStudent;teacherTab='student';renderTeacher();});const ss=$('#teacherStudentSelect');if(ss)ss.onchange=()=>{selectedStudent=teacherStudents.find(s=>s.id===ss.value)||selectedStudent;renderTeacher();};$$('[data-world-toggle]').forEach(i=>i.onchange=async()=>{try{const r=await api(`/api/teacher/students/${selectedStudent.id}/world-overrides`,{method:'POST',body:{worldId:i.dataset.worldToggle,value:i.checked}});selectedStudent.worldOverrides=r.worldOverrides;toast('Accès mis à jour')}catch(e){toast(e.message);i.checked=!i.checked;}});const form=$('#evidenceForm');if(form)form.onsubmit=async e=>{e.preventDefault();const criterion=$('#evCriterion').value;if(!criterion)return;const sid=selectedStudent.id;await api(`/api/teacher/students/${sid}/evidence`,{method:'POST',body:{criterion,score:+$('#evScore').value,type:$('#evType').value,date:$('#evDate').value,transfer:$('#evTransfer').checked,note:$('#evNote').value}});await loadTeacherStudents();selectedStudent=teacherStudents.find(s=>s.id===sid)||selectedStudent;toast('Preuve ajoutée');renderTeacher();};const all=$('#toggleAllSkills');if(all)all.onclick=()=>{teacherShowAllSkills=!teacherShowAllSkills;renderTeacher();};}


async function boot(){try{await loadResources();const st=await api('/api/status',{auth:false});if(!st.teacherConfigured){renderAuth('teacher');const slot=$('#authSlot');slot.innerHTML=`<div class="eyebrow">Première installation</div><h2>Initialiser le professeur</h2><form id="setupTeacher"><div class="field"><label>Nouveau PIN professeur</label><input id="setupPin" type="password" minlength="4" required></div><button class="login-btn">Initialiser →</button><div id="loginError" class="error"></div></form>`;$('#setupTeacher').onsubmit=async e=>{e.preventDefault();try{await api('/api/teacher/setup',{method:'POST',body:{pin:$('#setupPin').value},auth:false});toast('Professeur initialisé');renderAuth('teacher');}catch(err){$('#loginError').textContent=err.message;}};return;}renderAuth('student');}catch(err){APP.innerHTML=`<div class="auth-screen"><div class="card" style="max-width:720px"><h1>PédagoLab indisponible</h1><p>${esc(err.message)}</p><p class="muted">Vérifie <code>/api/status</code>, DATABASE_URL et SESSION_SECRET.</p></div></div>`;}}

const WORKER_SOURCE="function getFile(d,name){return d.files[name]??'';}\nfunction deepEq(a,b){return JSON.stringify(a)===JSON.stringify(b);}\nfunction execFunction(code,fnName,args=[]){try{const fn=Function(`${code}; return typeof ${fnName}==='function'?${fnName}:null;`)();if(typeof fn!=='function')return {ok:false,error:`Fonction ${fnName} introuvable`};return {ok:true,value:fn(...args)};}catch(e){return {ok:false,error:e.message};}}\nfunction testMission(m,d,index){const s=m.scenarios[index],v=m.validator;try{\n  if(v==='battery'){const val=Function(`${getFile(d,'battery.js')}`)();const pass=val===s.expected;return {pass,message:pass?`Réserve correcte : ${val}`:`Valeur obtenue ${val}; attendu ${s.expected}`};}\n  if(v==='motors'){const code=getFile(d,'motors.js');const val=Function('nombreModules',code)(s.input.nombreModules);const pass=deepEq(val,s.expected);return {pass,message:pass?`Tous les modules sont activés une fois.`:`Résultat ${JSON.stringify(val)}; attendu ${JSON.stringify(s.expected)}`};}\n  if(v==='card'){const h=getFile(d,'index.html'),c=getFile(d,'style.css');const pass=/<h2[^>]*>\\s*NOVA\\s*<\\/h2>/i.test(h)&&/class=[\"']actions[\"']/i.test(h)&&/\\.actions\\s*\\{[^}]*display\\s*:\\s*flex/is.test(c)&&/gap\\s*:/i.test(c);return {pass,message:pass?'Carte structurée et actions alignées.':'Vérifie le titre NOVA et .actions { display:flex; gap:... }'};}\n  if(v==='stationFinal'){const r=execFunction(getFile(d,'repair.js'),'repair',[s.input]);if(!r.ok)return {pass:false,message:r.error};const pass=deepEq(r.value,s.expected);return {pass,message:pass?'Rapport de réparation correct.':`Obtenu ${JSON.stringify(r.value)}; attendu ${JSON.stringify(s.expected)}`};}\n  if(v==='commandPwd'||v==='commandExact'||v==='answerExact'){const file=Object.keys(d.files)[0],val=getFile(d,file).trim();const pass=val===s.expected;return {pass,message:pass?'Commande correcte.':`Commande obtenue: ${val||'(vide)'}`};}\n  if(v==='healthcheck'){const r=execFunction(getFile(d,'healthcheck.js'),'healthcheck',[s.input.services]);if(!r.ok)return {pass:false,message:r.error};return {pass:deepEq(r.value,s.expected),message:deepEq(r.value,s.expected)?'Healthcheck correct.':`Incidents: ${JSON.stringify(r.value)}`};}\n  if(v==='distance'){const r=execFunction(getFile(d,'distance.js'),'distance',[s.input.dx,s.input.dy]);if(!r.ok)return {pass:false,message:r.error};const pass=Math.abs(Number(r.value)-s.expected)<1e-9;return {pass,message:pass?`Distance = ${r.value}`:`Distance obtenue ${r.value}; attendu ${s.expected}`};}\n  if(v==='returnArray'){const val=Function(getFile(d,'sequence.js'))();return {pass:deepEq(val,s.expected),message:deepEq(val,s.expected)?'Séquence correcte.':`Séquence ${JSON.stringify(val)}`};}\n  if(v==='countdown'){const r=execFunction(getFile(d,'countdown.js'),'countdown',[s.input.from]);if(!r.ok)return {pass:false,message:r.error};return {pass:deepEq(r.value,s.expected),message:deepEq(r.value,s.expected)?'Compte à rebours correct.':`Obtenu ${JSON.stringify(r.value)}`};}\n  if(v==='rocketFinal'){const r=execFunction(getFile(d,'launch.js'),'launchReport',[s.input.data]);if(!r.ok)return {pass:false,message:r.error};return {pass:deepEq(r.value,s.expected),message:deepEq(r.value,s.expected)?'Contrôleur de lancement validé.':`Rapport obtenu ${JSON.stringify(r.value)}`};}\n  if(v==='errors'){const r=execFunction(getFile(d,'logs.js'),'errors',[s.input.events]);if(!r.ok)return {pass:false,message:r.error};return {pass:deepEq(r.value,s.expected),message:deepEq(r.value,s.expected)?'Filtrage correct.':`Obtenu ${JSON.stringify(r.value)}`};}\n  if(v==='suspicious'){const r=execFunction(getFile(d,'anomaly.js'),'suspicious',[s.input.s]);if(!r.ok)return {pass:false,message:r.error};return {pass:r.value===s.expected,message:r.value===s.expected?'Décision correcte.':`Obtenu ${r.value}`};}\n  if(v==='incidentFinal'){const r=execFunction(getFile(d,'incident.js'),'incidentReport',[s.input.events,s.input.sessions]);if(!r.ok)return {pass:false,message:r.error};return {pass:deepEq(r.value,s.expected),message:deepEq(r.value,s.expected)?'Rapport incident validé.':`Obtenu ${JSON.stringify(r.value)}`};}\n  if(v==='activeCount'){const r=execFunction(getFile(d,'drones.js'),'activeCount',[s.input.drones]);if(!r.ok)return {pass:false,message:r.error};return {pass:r.value===s.expected,message:`Actifs: ${r.value}`};}\n  if(v==='droneAction'){const r=execFunction(getFile(d,'energy.js'),'action',[s.input.drone]);if(!r.ok)return {pass:false,message:r.error};return {pass:r.value===s.expected,message:`Action: ${r.value}`};}\n  if(v==='formation'){const r=execFunction(getFile(d,'formation.js'),'formation',[s.input.drones]);if(!r.ok)return {pass:false,message:r.error};return {pass:deepEq(r.value,s.expected),message:deepEq(r.value,s.expected)?'Formation correcte.':`Obtenu ${JSON.stringify(r.value)}`};}\n  if(v==='assaultFinal'){const r=execFunction(getFile(d,'controller.js'),'controller',[s.input.drones]);if(!r.ok)return {pass:false,message:r.error};return {pass:deepEq(r.value,s.expected),message:deepEq(r.value,s.expected)?'Contrôleur validé.':`Obtenu ${JSON.stringify(r.value)}`};}\n }catch(e){return {pass:false,message:'Erreur: '+e.message}}return {pass:false,message:'Validateur inconnu'};}\n\n\nself.onmessage=e=>{const {m,d,index}=e.data;self.postMessage(testMission(m,d,index));};";
async function workerTest(m,d,index){
 sendHost({type:'eden:event',eventType:'test_run',payload:{index}});
 const result=await new Promise(resolve=>{const url=URL.createObjectURL(new Blob([WORKER_SOURCE],{type:'text/javascript'})),w=new Worker(url);let settled=false;const finish=r=>{if(settled)return;settled=true;clearTimeout(timer);w.terminate();URL.revokeObjectURL(url);resolve(r);};const timer=setTimeout(()=>finish({pass:false,message:'Temps maximal dépassé (1 seconde). Simplifie ou fais relire le code.'}),1000);w.onmessage=e=>finish({pass:e.data?.pass===true,message:String(e.data?.message||'').slice(0,3000)});w.onerror=()=>finish({pass:false,message:'Exécution indisponible : demander une relecture.'});w.postMessage({m,d,index});});
 sendHost({type:'eden:event',eventType:result.pass?'test_passed':'test_failed',payload:{index,result}});return result;
}
let hostPort=null;
function sendHost(message){if(hostPort)hostPort.postMessage(message);else parent.postMessage(message,'*');}
function initHost(c){if(c?.type!=='eden:init'||session.role)return;WORLDS=c.worlds;resources=c.resources;session.role='student';session.user=c.user;session.worldOverrides={[c.worldId]:true};session.progressRoot={platform:c.progress||defaultPlatform()};platform().callsign=c.user.displayName;activeWorld=c.worldId;activeMission=c.missionId;renderWorld();sendHost({type:'eden:event',eventType:'mission_started',payload:{}});}
window.addEventListener('message',e=>{if(e.source!==parent||session.role||hostPort)return;if(e.data?.type==='eden:connect'&&e.ports.length===1){hostPort=e.ports[0];hostPort.onmessage=event=>initHost(event.data);hostPort.start();}else initHost(e.data);});
parent.postMessage({type:'eden:ready'},'*');

})();
